"""Compute dataset statistics from the generated files and write documentation/dataset_statistics.md.

Every number in the report is computed here from raw_data/<mode>/ - nothing is typed by hand.
Statistics describe the raw data *as generated*: where a statistic would be distorted by the
injected defects (e.g. negative counts), those rows are excluded and the report says so.

Usage: python -m data_generator.dataset_stats --mode full
"""

import argparse
import json
from pathlib import Path

import numpy as np
import pandas as pd
import yaml

PROJECT_ROOT = Path(__file__).resolve().parent.parent
TS = "%Y-%m-%d %H:%M:%S"
DOW = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"]


def _read(path, cols, **kw):
    return pd.read_csv(path, usecols=cols, dtype=str, keep_default_na=False, **kw)


def _ts(s):
    return pd.to_datetime(s, format=TS, errors="coerce")


def _md_table(df: pd.DataFrame, floatfmt="{:,.2f}") -> str:
    """Render a small DataFrame as a Markdown table."""
    cols = list(df.columns)
    out = ["| " + " | ".join(str(c) for c in cols) + " |", "|" + "---|" * len(cols)]
    for row in df.itertuples(index=False):        # itertuples keeps each column's own type
        cells = []
        for v in row:
            if isinstance(v, (float, np.floating)):
                cells.append(floatfmt.format(v))
            elif isinstance(v, (int, np.integer)):
                cells.append(f"{v:,}")
            else:
                cells.append(str(v))
        out.append("| " + " | ".join(cells) + " |")
    return "\n".join(out)


def load(data: Path):
    trips = pd.concat([_read(f, ["trip_id", "route_id", "direction", "service_date", "scheduled_departure",
                                 "scheduled_arrival", "actual_departure", "actual_arrival", "trip_status",
                                 "trip_type", "cancellation_reason", "original_vehicle_id"])
                       for f in sorted((data / "trips").glob("*.csv"))], ignore_index=True)
    trips = trips.drop_duplicates("trip_id")
    for c in ("scheduled_departure", "scheduled_arrival", "actual_departure", "actual_arrival"):
        trips[c] = _ts(trips[c])
    trips["service_date"] = pd.to_datetime(trips.service_date)
    for c in ("route_id", "trip_status", "trip_type", "cancellation_reason", "direction"):
        trips[c] = trips[c].astype("category")
    pc = pd.concat([_read(f, ["trip_id", "vehicle_id", "service_date", "boardings", "max_load", "denied_boardings", "card_taps"])
                    for f in sorted((data / "passenger_counts").glob("*.csv"))], ignore_index=True)
    for c in ("boardings", "max_load", "denied_boardings", "card_taps"):
        pc[c] = pc[c].astype(int)
    pc["service_date"] = pd.to_datetime(pc.service_date)
    delays = pd.concat([_read(f, ["trip_id", "stop_id", "service_date", "scheduled_arrival", "delay_minutes", "delay_reason"])
                        for f in sorted((data / "delays").glob("*.csv"))], ignore_index=True)
    delays["delay_minutes"] = pd.to_numeric(delays.delay_minutes, errors="coerce")
    delays["scheduled_arrival"] = _ts(delays.scheduled_arrival)
    return trips, pc, delays


def build_report(mode: str, data: Path) -> str:
    summary = json.loads((PROJECT_ROOT / "data_generator" / "manifests" / mode / "generation_summary.json").read_text())
    manifest = json.loads((PROJECT_ROOT / "data_generator" / "manifests" / mode / "injection_manifest.json").read_text())
    thresholds = yaml.safe_load((PROJECT_ROOT / "config" / "thresholds.yaml").read_text())
    vehicles = _read(data / "vehicles" / "vehicles.csv", ["vehicle_id", "capacity_total"])
    cap = dict(zip(vehicles.vehicle_id, vehicles.capacity_total.astype(int)))
    routes = _read(data / "routes" / "routes.csv", ["route_id", "route_code", "route_type", "launch_date"])
    stops = _read(data / "stops" / "stops.csv", ["stop_id", "stop_name", "opened_date"])
    route_stops = _read(data / "route_stops" / "route_stops.csv", ["route_id", "stop_id"])
    calendar = json.loads((data / "service_calendar" / "service_calendar.json").read_text())
    schedules = _read(data / "schedules" / "schedules.csv", ["service_id", "route_id"])
    start, end = pd.Timestamp(summary["start_date"]), pd.Timestamp(summary["end_date"])

    trips, pc, delays = load(data)
    ok_pc = pc[(pc.boardings >= 0) & (pc.max_load >= 0)].copy()
    ok_pc["capacity"] = ok_pc.vehicle_id.map(cap)
    ok_pc = ok_pc[ok_pc.max_load <= 1.5 * ok_pc.capacity]            # drop injected impossible loads
    ok_pc["occupancy"] = ok_pc.max_load / ok_pc.capacity
    ok_pc = ok_pc.merge(trips[["trip_id", "route_id", "direction", "scheduled_departure", "trip_type"]], on="trip_id", how="inner")
    ok_pc["hour"] = ok_pc.scheduled_departure.dt.hour
    ok_pc["dow"] = ok_pc.service_date.dt.dayofweek

    L = [f"# Dataset Statistics - `{mode}` mode", "",
         f"_Generated by `data_generator/dataset_stats.py` from `raw_data/{mode}/` (seed {summary['seed']}, "
         f"network seed {summary['network_seed']}). All numbers are computed from the generated files._", "",
         "Unless stated otherwise, statistics use the raw files as generated (injected defects included). "
         "Occupancy and boardings statistics exclude the injected negative counts and impossible loads "
         f"({len(pc) - len(ok_pc):,} passenger_counts rows) and use trips present in `trips` only.", ""]

    # ---- volumes
    rc = summary["row_counts"]
    L += ["## 1. Volumes", "",
          _md_table(pd.DataFrame([{"table": k, "rows": int(v)} for k, v in rc.items()])), "",
          f"- Files: {summary['files']}, total size {summary['total_bytes'] / 1e6:,.1f} MB, generation time {summary['elapsed_seconds']:,.0f} s.",
          f"- Distinct ticket IDs: {manifest['row_counts']['tickets'] - next((d['rows'] for d in manifest['defects'] if d['defect'] == 'duplicate_tickets'), 0):,} "
          f"(rows minus injected duplicates).", ""]

    # ---- time coverage and seasonality
    op = trips[trips.trip_status == "completed"]
    monthly = pd.DataFrame({
        "trips_operated": op.groupby(op.service_date.dt.to_period("M")).size(),
        "boardings_apc": ok_pc.groupby(ok_pc.service_date.dt.to_period("M")).boardings.sum(),
        "avg_daily_boardings": ok_pc.groupby(ok_pc.service_date.dt.to_period("M")).boardings.sum()
                                / ok_pc.groupby(ok_pc.service_date.dt.to_period("M")).service_date.nunique(),
        "card_taps": ok_pc.groupby(ok_pc.service_date.dt.to_period("M")).card_taps.sum(),
    })
    tickets_per_month = {}
    for f in sorted((data / "tickets").glob("*.csv")):
        tickets_per_month[f.stem.split("_")[-1]] = sum(1 for _ in open(f, encoding="utf-8")) - 1
    monthly["ticket_rows"] = [tickets_per_month.get(str(p), 0) for p in monthly.index]
    monthly["card_share_%"] = monthly.card_taps / monthly.boardings_apc * 100
    monthly.index = monthly.index.astype(str)
    peak_m, low_m = monthly.avg_daily_boardings.idxmax(), monthly.avg_daily_boardings.idxmin()
    L += ["## 2. Time coverage and seasonal demand", "",
          f"- Service dates {trips.service_date.min().date()} to {trips.service_date.max().date()}: "
          f"{trips.service_date.nunique()} days in {trips.service_date.dt.to_period('M').nunique()} calendar months.",
          f"- Busiest month (average daily APC boardings): **{peak_m}**; quietest: **{low_m}** "
          f"({monthly.avg_daily_boardings.min() / monthly.avg_daily_boardings.max() * 100:.0f}% of the busiest month).",
          "- The card share rises through the year (smart-card adoption), so ticket rows grow even when ridership falls.", "",
          _md_table(monthly.reset_index().rename(columns={"index": "month", "service_date": "month"})), ""]

    # ---- weekday / weekend
    daily = ok_pc.groupby("service_date").boardings.sum().to_frame("boardings")
    daily["dow"] = daily.index.dayofweek
    hol_dates = {pd.Timestamp(e["date"]) for s in calendar if s["service_id"] == "HOL" for e in s["exceptions"]}
    daily["holiday"] = daily.index.isin(hol_dates)
    dow_tab = daily[~daily.holiday].groupby("dow").boardings.mean()
    wk, we = dow_tab.loc[0:4].mean(), dow_tab.loc[5:6].mean()
    L += ["## 3. Weekday / weekend and holidays", "",
          _md_table(pd.DataFrame({"day": [DOW[i] for i in dow_tab.index], "avg_daily_boardings": dow_tab.values})), "",
          f"- Average weekend day = **{we / wk * 100:.0f}%** of an average weekday (non-holiday days).",
          f"- Public holidays ({int(daily.holiday.sum())} days in data): average **{daily[daily.holiday].boardings.mean():,.0f}** "
          f"boardings/day vs **{wk:,.0f}** on normal weekdays." if daily.holiday.any() else "- No public holidays in this period.", ""]

    # ---- peaks
    wkday = ok_pc[ok_pc.dow < 5]
    hourly = wkday.groupby("hour").boardings.sum() / wkday.service_date.nunique()
    weh = ok_pc[ok_pc.dow >= 5]
    hourly_we = weh.groupby("hour").boardings.sum() / max(1, weh.service_date.nunique())
    htab = pd.DataFrame({"hour": hourly.index, "weekday_avg_boardings": hourly.values,
                         "weekend_avg_boardings": hourly_we.reindex(hourly.index, fill_value=0).values})
    L += ["## 4. Peak hours (boardings by scheduled departure hour)", "",
          f"- Weekday peaks: **{int(hourly.loc[5:11].idxmax()):02d}:00** (morning) and **{int(hourly.loc[14:21].idxmax()):02d}:00** (evening); "
          f"weekend peak **{int(hourly_we.idxmax()):02d}:00** (single, flatter midday/evening peak).", "",
          _md_table(htab, "{:,.0f}"), ""]

    # ---- direction
    am = wkday[(wkday.hour >= 7) & (wkday.hour < 10)]
    pm = wkday[(wkday.hour >= 16) & (wkday.hour < 19)]
    amr = am.groupby(["route_id", "direction"], observed=True).boardings.mean().unstack()
    pmr = pm.groupby(["route_id", "direction"], observed=True).boardings.mean().unstack()
    ratio_am = (amr["0"] / amr["1"]).dropna()
    ratio_pm = (pmr["0"] / pmr["1"]).dropna()
    flips = ((ratio_am > 1) != (ratio_pm > 1)).mean() * 100
    L += ["## 5. Route direction differences", "",
          f"- Weekday AM peak: median ratio between the busier and quieter direction of a route = "
          f"**{np.median(np.maximum(ratio_am, 1 / ratio_am)):.2f}x**.",
          f"- For **{flips:.0f}%** of routes the busier direction flips between the AM and PM peak (inbound in the morning, outbound in the evening).", ""]

    # ---- occupancy
    cats = thresholds["occupancy_categories"]
    edges = [0] + [c["max_ratio"] for c in cats[:-1]] + [np.inf]
    ok_pc["occ_cat"] = pd.cut(ok_pc.occupancy, edges, labels=[c["name"] for c in cats], include_lowest=True)
    occ = ok_pc.occ_cat.value_counts(normalize=True).reindex([c["name"] for c in cats]) * 100
    rt = ok_pc.merge(routes[["route_id", "route_type"]], on="route_id")
    by_type = rt.groupby("route_type").occupancy.mean()
    route_occ = ok_pc.groupby("route_id", observed=True).occupancy.mean()
    L += ["## 6. Occupancy (max load / vehicle capacity, categories from config/thresholds.yaml)", "",
          _md_table(pd.DataFrame({"category": occ.index, "share_of_trips_%": occ.values})), "",
          f"- Trips that left passengers behind (denied boardings > 0): **{(ok_pc.denied_boardings > 0).mean() * 100:.2f}%**.",
          f"- Low-demand routes (mean occupancy < 0.2): **{(route_occ < 0.2).sum()}**; routes with mean occupancy > 0.6: **{(route_occ > 0.6).sum()}**.",
          "- Mean occupancy by route type: " + ", ".join(f"{k} {v:.2f}" for k, v in by_type.items()) + ".", ""]

    # ---- delays
    d = delays.dropna(subset=["delay_minutes"])
    d = d[d.delay_minutes.between(-60, 600)]
    reasons = d.delay_reason.value_counts()
    # trip-level end delay (last stop): every operated trip, not only the logged delay records
    td = op[["trip_id", "scheduled_departure", "scheduled_arrival", "actual_arrival"]].copy()
    td["end_delay"] = (td.actual_arrival - td.scheduled_arrival).dt.total_seconds() / 60
    td["hour"] = td.scheduled_departure.dt.hour
    tj = td.merge(ok_pc[["trip_id", "occupancy"]], on="trip_id", how="inner")
    tj["occ_band"] = pd.cut(tj.occupancy, [0, 0.4, 0.7, 0.9, 1.1, np.inf], labels=["<0.4", "0.4-0.7", "0.7-0.9", "0.9-1.1", ">1.1"],
                            include_lowest=True)
    by_occ = tj.groupby("occ_band", observed=True).end_delay.agg(["mean", lambda x: (x > 5).mean() * 100, "size"])
    by_occ.columns = ["mean_end_delay_min", "late_over_5min_%", "trips"]
    peak_h = td.hour.isin([7, 8, 9, 16, 17, 18])
    corr = tj[["occupancy", "end_delay"]].corr().iloc[0, 1]
    by_hour = td.groupby("hour").end_delay.agg(["mean", lambda x: (x > 5).mean() * 100])
    by_hour.columns = ["mean_end_delay_min", "late_over_5min_%"]
    stop_deg = route_stops.groupby("stop_id").route_id.nunique()
    top_stops = d[d.delay_minutes > 0].groupby("stop_id").delay_minutes.agg(["size", "mean"]).sort_values("size", ascending=False).head(10)
    top_stops["routes_serving"] = stop_deg.reindex(top_stops.index).values
    top_stops = top_stops.reset_index().merge(stops[["stop_id", "stop_name"]], on="stop_id")
    L += ["## 7. Delays", "",
          f"- Delay records: {len(delays):,} ({len(d):,} with a valid numeric value in [-60, 600]); "
          f"late records mean **{d[d.delay_minutes > 0].delay_minutes.mean():.1f} min**, "
          f"early-running records: **{(d.delay_minutes < 0).sum():,}**.",
          f"- Trip-level end delay (actual - scheduled arrival at the last stop, all operated trips): mean "
          f"**{td.end_delay.mean():.2f} min**, late > 5 min **{(td.end_delay > 5).mean() * 100:.1f}%**.",
          f"- **Time of day:** peak hours (07-09, 16-18) mean **{td[peak_h].end_delay.mean():.2f} min** "
          f"({(td[peak_h].end_delay > 5).mean() * 100:.1f}% late) vs off-peak **{td[~peak_h].end_delay.mean():.2f} min** "
          f"({(td[~peak_h].end_delay > 5).mean() * 100:.1f}% late).",
          f"- **Load:** correlation between occupancy and end delay r = **{corr:.2f}**; by occupancy band:", "",
          _md_table(by_occ.reset_index().rename(columns={"occ_band": "occupancy"})), "",
          "End delay by scheduled departure hour:", "",
          _md_table(by_hour.reset_index()), "",
          "Delay reasons (logged records):", "",
          _md_table(pd.DataFrame({"reason": reasons.index, "records": reasons.values})), "",
          "Top 10 stops by number of late records - the most shared stops (bottleneck junctions) dominate:", "",
          _md_table(top_stops[["stop_id", "stop_name", "size", "mean", "routes_serving"]].rename(
              columns={"size": "late_records", "mean": "mean_delay_min"})), ""]

    # ---- headways, bunching, cancellations, early arrivals, vehicle changes
    op = op.sort_values(["route_id", "direction", "service_date", "scheduled_departure"])
    grp = op.groupby(["route_id", "direction", "service_date"], observed=True)
    sch_hw = grp.scheduled_departure.diff().dt.total_seconds() / 60
    ratios = {}
    for col, label in (("actual_departure", "first stop (departure)"), ("actual_arrival", "last stop (arrival)")):
        r = (grp[col].diff().dt.total_seconds() / 60 / sch_hw).replace([np.inf, -np.inf], np.nan)
        ratios[label] = r[(sch_hw >= 5)].dropna()
    thr = thresholds["bunching"]
    cancelled = trips[trips.trip_status == "cancelled"]
    early_arr = ((op.scheduled_arrival - op.actual_arrival).dt.total_seconds() > 60).mean() * 100
    L += ["## 8. Headways, bunching, cancellations, early arrivals, vehicle changes", "",
          "Headway ratio = actual / scheduled time between consecutive trips of the same route, direction and day "
          f"(bunched < {thr['headway_ratio_threshold']}, gap > {thr['gap_ratio_threshold']}, thresholds from config/thresholds.yaml):", "",
          _md_table(pd.DataFrame([{"measured at": k, "headways": len(v), "coefficient_of_variation": v.std() / v.mean(),
                                   "bunched_%": (v < thr["headway_ratio_threshold"]).mean() * 100,
                                   "gaps_%": (v > thr["gap_ratio_threshold"]).mean() * 100} for k, v in ratios.items()])), "",
          "- Departures leave the terminal close to the timetable; irregularity grows along the route "
          "(a late bus picks up more passengers and loses more time, the next one catches up), so bunching shows at the last stop.",
          f"- Cancelled trips: **{len(cancelled):,}** ({len(cancelled) / len(trips) * 100:.2f}%). Reasons: "
          + ", ".join(f"{k} {v:,}" for k, v in cancelled.cancellation_reason.value_counts().items() if v) + ".",
          f"- Trips arriving more than 1 minute early at the last stop: **{early_arr:.1f}%** of operated trips.",
          f"- Vehicle changes (breakdown swaps, `original_vehicle_id` set): **{(trips.original_vehicle_id != '').sum():,}** trips.", ""]

    # ---- events
    ev_cfg = yaml.safe_load((PROJECT_ROOT / "data_generator" / "generator_config.yaml").read_text())["common"]["events"]
    rows = []
    for ev in ev_cfg:
        day = pd.Timestamp(str(ev["date"]))
        if not (start <= day <= end):
            continue
        extra = ok_pc[(ok_pc.service_date == day) & (ok_pc.trip_type == "event_extra")]
        routes_ev = set(extra.route_id)
        h0 = int(str(ev["start"])[:2]) - 2
        h1 = int(str(ev["end"])[:2]) + 1
        in_win = ok_pc.hour.between(h0, h1) & ok_pc.route_id.isin(routes_ev)
        # baseline: the same weekday in the same month, same routes and same hours, excluding the event day
        same_dow = ok_pc[in_win & (ok_pc.dow == day.dayofweek) & (ok_pc.service_date.dt.to_period("M") == day.to_period("M"))
                         & (ok_pc.service_date != day)]
        base = same_dow.groupby("service_date").boardings.sum().mean()
        on_day = ok_pc[in_win & (ok_pc.service_date == day)].boardings.sum()
        rows.append({"date": str(day.date()), "event": ev["name"], "venue": ev["venue"], "extra_trips": len(extra),
                     "routes": len(routes_ev), "window": f"{h0:02d}-{h1:02d}h", "boardings_in_window": int(on_day),
                     "same_weekday_avg": float(base) if base == base else 0.0,
                     "uplift_%": (on_day / base - 1) * 100 if base and base == base else 0.0})
    L += ["## 9. Special events and passenger spikes", "",
          "Boardings on the routes serving the venue during the event window, compared with the same weekday "
          "(same month, same routes, same hours). Holidays depress the baseline comparison when the event is on a public holiday.", "",
          _md_table(pd.DataFrame(rows)) if rows else "No events in this period.", ""]

    # ---- growth: new routes, stops, schedules
    new_routes = routes[pd.to_datetime(routes.launch_date).between(start, end)]
    nr_rows = []
    for _, r in new_routes.iterrows():
        tr = trips[trips.route_id == r.route_id]
        nr_rows.append({"route_id": r.route_id, "code": r.route_code, "type": r.route_type, "launch_date": r.launch_date,
                        "first_trip": str(tr.service_date.min().date()) if len(tr) else "-", "trips": len(tr)})
    new_stops = stops[pd.to_datetime(stops.opened_date).between(start, end)]
    per_period = pd.Series({s["service_id"]: s["timetable_period"] for s in calendar})
    sched_period = schedules.service_id.map(per_period).value_counts()
    L += ["## 10. Network growth: new routes, stops and schedules", "",
          f"- Routes launched during the period: **{len(new_routes)}**; stops opened during the period: **{len(new_stops)}**.",
          f"- Service calendars: **{len(calendar)}** ({', '.join(s['service_id'] for s in calendar)}).",
          "- Schedule rows per timetable period: " + ", ".join(f"{k} {v:,}" for k, v in sched_period.items()) + ".", "",
          _md_table(pd.DataFrame(nr_rows)) if nr_rows else "", ""]

    # ---- passengers and tickets
    pax = _read(data / "passengers" / "passengers.csv", ["passenger_id", "passenger_type", "registration_date"])
    t_counts, fares = pd.Series(dtype=float), []
    for f in sorted((data / "tickets").glob("*.csv")):
        k = _read(f, ["passenger_id", "ticket_type", "fare_amount"])
        t_counts = t_counts.add(k.passenger_id.value_counts(), fill_value=0)
        fares.append(k.assign(fare_amount=pd.to_numeric(k.fare_amount, errors="coerce")).groupby("ticket_type").fare_amount.agg(["sum", "size"]))
    fares = pd.concat(fares).groupby(level=0).sum()
    known = t_counts[t_counts.index.isin(set(pax.passenger_id))]
    reg = pd.to_datetime(pax.registration_date)
    L += ["## 11. Passengers and tickets", "",
          f"- Registered passengers: **{len(pax):,}** ({(reg >= start).sum():,} registered during the period); "
          f"passenger types: " + ", ".join(f"{k} {v:,}" for k, v in pax.passenger_type.value_counts().items()) + ".",
          f"- Passengers with at least one ticket: **{len(known):,}**; tickets per active passenger: median "
          f"**{known.median():.0f}**, 90th percentile **{known.quantile(0.9):.0f}**, max **{known.max():.0f}**.",
          "- Tickets by type: " + ", ".join(f"{k} {int(v['size']):,} (avg fare {v['sum'] / v['size']:.1f} PKR)" for k, v in fares.iterrows()) + ".", ""]

    # ---- GPS
    gps_files = sorted((data / "gps_events").glob("*.jsonl"))
    L += ["## 12. GPS events", "",
          f"- {rc['gps_events']:,} events in {len(gps_files)} daily JSON Lines files "
          f"({gps_files[0].stem.split('_')[-1]} to {gps_files[-1].stem.split('_')[-1]}), "
          f"{sum(f.stat().st_size for f in gps_files) / 1e6:,.1f} MB.", ""]

    # ---- defects
    L += ["## 13. Injected defects (from the manifest)", "",
          _md_table(pd.DataFrame([{"defect": x["defect"], "table": x["table"], "rows": x["rows"]} for x in manifest["defects"]])), "",
          "Orphans created by removed trips: " + ", ".join(f"{k} {v:,}" for k, v in manifest["missing_trip_records_orphans"].items()) + ".", ""]
    return "\n".join(L)


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--mode", default="full")
    ap.add_argument("--out", type=Path)
    args = ap.parse_args()
    data = PROJECT_ROOT / "raw_data" / args.mode
    out = args.out or PROJECT_ROOT / "documentation" / ("dataset_statistics.md" if args.mode == "full" else f"dataset_statistics_{args.mode}.md")
    out.write_text(build_report(args.mode, data), encoding="utf-8")
    print(f"wrote {out}")


if __name__ == "__main__":
    main()
